package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import java.util.*;import java.nio.charset.StandardCharsets;import java.time.LocalDateTime;
import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
/** Immutable publication intent and exactly one initial object attempt. Recovery can never send again. */
public final class FormalAgentPublicationObjectLedger {
 private final JdbcTemplate db;private final FormalAgentPublicationSchema schema;private final PermissionSchema json;
 public FormalAgentPublicationObjectLedger(DataSource data,FormalAgentPublicationSchema schema,PermissionSchema json){this(new JdbcTemplate(data),schema,json);}
 FormalAgentPublicationObjectLedger(JdbcTemplate db,FormalAgentPublicationSchema schema,PermissionSchema json){this.db=db;db.setQueryTimeout(5);this.schema=schema;this.json=json;}
 public static final String OPERATION="FORMAL-AGENT-PUBLISH";
 record Row(String tenant,String project,String actor,String key,String operation,String write,String artifact,String acceptance,String acceptanceHash,String candidate,String candidateHash,String expectedRevision,String request,String requestHash,String payload,String payloadHash,String objectKey,String authority,String authorityHash,String identityMode,String schemaVersion,String schemaManifest,String classification,LocalDateTime created,LocalDateTime deadline,String release){}
 record Operation(String id,String requestHash,String state,int revision,String response,String target,String schemaVersion,String manifest,LocalDateTime created,String creator,String classification,int httpStatus,LocalDateTime updated){}
 Row row(Attempt attempt){return attempt.row;}
 public static final class Attempt implements RuntimeObjectAttempt {
  private final Row row;private final boolean prior;private final String currentActor;private final java.util.concurrent.atomic.AtomicBoolean consumed=new java.util.concurrent.atomic.AtomicBoolean();
  private Attempt(Row row,boolean prior,String currentActor){this.row=row;this.prior=prior;this.currentActor=currentActor;}
  public String tenantId(){return row.tenant();}public String actorId(){return currentActor;}public String expectedObjectKey(){return key(row.tenant(),row.release(),row.write(),row.artifact());}
  public S3ObjectWriter.WriteIntent writeIntent(){return new S3ObjectWriter.WriteIntent(row.write(),row.objectKey(),row.payloadHash(),Integer.toString(bytes().length),"application/json");}
  public byte[] bytes(){return row.payload().getBytes(StandardCharsets.UTF_8);}public boolean priorAttempt(){return prior;}
  public TransferMode claimTransferMode(){return prior||!consumed.compareAndSet(false,true)?TransferMode.RECOVER_ONLY:TransferMode.INITIAL_WRITE;}
  public String releaseId(){return row.release();}public String plannedArtifactId(){return row.artifact();}public String operationId(){return row.operation();}public String projectId(){return row.project();}public PermissionProtocol.Basis acceptance(){return new PermissionProtocol.Basis(row.acceptance(),row.acceptanceHash());}
 }
 Row inspect(EnterpriseAccess.Admission a,String originalKey)throws Exception{scope(a);SimulationInputArtifactSchema.key(originalKey);var rows=rows(a,originalKey);var operations=operations(a,originalKey);if(rows.isEmpty()!=operations.isEmpty())bad();if(rows.isEmpty())return null;var row=one(rows);verify(a,row);if(one(operations).revision()>=2)attempt(a,row,false);return row;}
 boolean completed(EnterpriseAccess.Admission a,Row row)throws Exception{scope(a);verify(a,row);return "COMPLETED".equals(one(operations(a,row.actor(),row.key())).state());}
 Attempt prepare(EnterpriseAccess.Admission a,String originalKey,JsonNode request,FormalAgentPublicationAuthorization.Verified proof)throws Exception {
  scope(a);proof.requireWrite(a);schema.validate("Publish",request);SimulationInputArtifactSchema.key(originalKey);
  if(!proof.acceptance().equals(FormalAgentCandidateDependencies.basis(request.required("acceptance")))||!proof.manifest().manifest().agentVersionId().equals(request.path("candidate").path("version_id").asText())||!proof.manifest().manifest().agentVersionSha256().equals(request.path("candidate").path("content_sha256").asText()))bad();
  String requestJson=schema.canonical(request),requestHash=requestHash(a.context().tenant_id(),a.actorId(),request);var existing=rows(a,originalKey);
  var operation=operations(a,originalKey);if(existing.isEmpty()!=operation.isEmpty())bad();
  if(existing.isEmpty()){
   if(!proof.candidateRevision().equals(request.path("expected_revision").asText())||!"REVIEW_PENDING".equals(proof.candidateStatus()))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
   String write=id(),artifact=id(),op=id(),release=proof.manifest().manifest().releaseId(),payload=proof.manifest().canonicalJson();var now=now();var deadline=now.plusMinutes(5);
   var auth=proof.authorizations();((com.fasterxml.jackson.databind.node.ObjectNode)auth).put("identity_mode",a.bindingView().mode());String authority=schema.canonical(auth);
   var row=new Row(a.context().tenant_id(),proof.projectId(),a.actorId(),originalKey,op,write,artifact,proof.acceptance().version_id(),proof.acceptance().content_sha256(),proof.manifest().manifest().agentVersionId(),proof.manifest().manifest().agentVersionSha256(),request.path("expected_revision").asText(),requestJson,requestHash,payload,proof.manifest().sha256(),key(a.context().tenant_id(),release,write,artifact),authority,schema.hash(auth),a.bindingView().mode(),"1.0.0",schema.manifest(),proof.classification(),now,deadline,release);
   one(db.update("INSERT INTO operation_record(tenant_id,operation_id,subject_id,operation_name,idempotency_key,request_sha256,state,http_status,response_ref,target_id,schema_version,schema_manifest_sha256,created_by,created_at,classification,revision,updated_at) VALUES(?,?,?,?,?,?,'PROCESSING',202,NULL,?,'1.0.0',?,?,?, ?,1,?)",row.tenant(),op,row.actor(),OPERATION,originalKey,requestHash,release,schema.manifest(),row.actor(),now,row.classification(),now));
   one(db.update("""
    INSERT INTO formal_agent_publication_intent(tenant_id,project_id,created_by,idempotency_key,operation_id,write_id,artifact_id,acceptance_id,acceptance_sha256,candidate_version_id,candidate_sha256,expected_revision,request_json,request_sha256,canonical_payload,payload_sha256,object_key,authorizations_json,authorizations_sha256,identity_mode,schema_version,schema_manifest_sha256,classification,created_at,deadline,release_id)
    VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'1.0.0',?,?,?,?,?)
    """,row.tenant(),row.project(),row.actor(),row.key(),row.operation(),row.write(),row.artifact(),row.acceptance(),row.acceptanceHash(),row.candidate(),row.candidateHash(),row.expectedRevision(),row.request(),row.requestHash(),row.payload(),row.payloadHash(),row.objectKey(),row.authority(),row.authorityHash(),row.identityMode(),row.schemaManifest(),row.classification(),row.created(),row.deadline(),row.release()));
   String anchor=anchor(row);one(db.update("INSERT INTO audit_event(tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,'agent.publication.prepared',?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",row.tenant(),row.project(),id(),row.actor(),anchor,row.operation(),row.write(),row.schemaManifest(),row.actor(),row.created(),row.classification()));
   one(db.update("INSERT INTO outbox_event(tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES(?,?,?,1,'agent.publication.prepared',?,?)",row.tenant(),row.write(),row.release(),anchor,row.created()));
   existing=rows(a,originalKey);
  }
  var row=one(existing);verify(a,row);if(!row.requestHash().equals(requestHash))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);
  if(!row.payload().equals(proof.manifest().canonicalJson())||!row.acceptance().equals(proof.acceptance().version_id())||!row.acceptanceHash().equals(proof.acceptance().content_sha256())||!Objects.equals(row.project(),proof.projectId()))bad();
  return attempt(a,row,true);
 }
 Attempt recover(EnterpriseAccess.Admission a,String originalKey,FormalAgentPublicationAuthorization.Verified proof)throws Exception {scope(a);proof.requireRead(a);var row=one(rows(a,originalKey));verify(a,row);if(!row.payload().equals(proof.manifest().canonicalJson())||!row.acceptance().equals(proof.acceptance().version_id())||!row.acceptanceHash().equals(proof.acceptance().content_sha256()))bad();return attempt(a,row,false);}
 Attempt readPublishedAttempt(EnterpriseAccess.Admission a,String releaseId,FormalAgentPublicationAuthorization.Verified proof)throws Exception{
  scope(a);proof.requireRead(a);WireValues.uuid(releaseId);
  var identity=one(db.query("SELECT created_by,idempotency_key FROM formal_agent_publication_intent WHERE tenant_id=? AND release_id=? LIMIT 2",(r,n)->Map.entry(r.getString(1),r.getString(2)),a.context().tenant_id(),releaseId));
  var row=one(rows(a,identity.getKey(),identity.getValue()));verify(a,row);
  if(!row.release().equals(releaseId)||!row.payload().equals(proof.manifest().canonicalJson())||!row.acceptance().equals(proof.acceptance().version_id())||!row.acceptanceHash().equals(proof.acceptance().content_sha256())||!"COMPLETED".equals(one(operations(a,row.actor(),row.key())).state()))bad();
  return attempt(a,row,false);
 }
 void requireAttempt(EnterpriseAccess.Admission a,Attempt expected)throws Exception {scope(a);if(!a.actorId().equals(expected.actorId()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);var row=one(rows(a,expected.row.actor(),expected.row.key()));verify(a,row);if(!row.equals(expected.row))bad();attempt(a,row,false);}
 private Attempt attempt(EnterpriseAccess.Admission a,Row row,boolean create)throws Exception {
  var op=one(operations(a,row.actor(),row.key()));var attempts=db.query("SELECT created_at FROM formal_agent_publication_attempt WHERE tenant_id=? AND write_id=? AND operation_id=? AND release_id=? AND project_id <=> ? AND created_by=? AND intent_sha256=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND classification=? LIMIT 2 FOR UPDATE",(r,n)->r.getTimestamp(1).toLocalDateTime(),row.tenant(),row.write(),row.operation(),row.release(),row.project(),row.actor(),schema.hash(AgentPublicationWitness.tree(row)),row.schemaManifest(),row.classification());
  if(attempts.size()>1)bad();boolean prior=!attempts.isEmpty();if(prior){if(op.revision()<2||attempts.get(0).isBefore(row.created())||!attempts.get(0).isBefore(row.deadline())||attempts.get(0).isAfter(now())||op.updated().isBefore(attempts.get(0))||("PROCESSING".equals(op.state())&&!op.updated().equals(attempts.get(0))))bad();return new Attempt(row,true,a.actorId());}
  if(!create||op.revision()!=1||!"PROCESSING".equals(op.state()))bad();var now=now();if(!now.isBefore(row.deadline()))throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
  one(db.update("INSERT INTO formal_agent_publication_attempt(tenant_id,project_id,write_id,operation_id,release_id,intent_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,'1.0.0',?,?,?,?)",row.tenant(),row.project(),row.write(),row.operation(),row.release(),schema.hash(AgentPublicationWitness.tree(row)),row.schemaManifest(),row.actor(),now,row.classification()));
  one(db.update("UPDATE operation_record SET revision=2,updated_at=? WHERE tenant_id=? AND operation_id=? AND subject_id=? AND operation_name=? AND idempotency_key=? AND state='PROCESSING' AND revision=1",now,row.tenant(),row.operation(),row.actor(),OPERATION,row.key()));
  var readback=attempt(a,row,false);if(!readback.priorAttempt())bad();return new Attempt(row,false,a.actorId());
 }
 private void verify(EnterpriseAccess.Admission a,Row row)throws Exception {
  if(!row.tenant().equals(a.context().tenant_id())||!"1.0.0".equals(row.schemaVersion())||!schema.manifest().equals(row.schemaManifest())||!key(row.tenant(),row.release(),row.write(),row.artifact()).equals(row.objectKey())||!row.created().isBefore(row.deadline())||!row.deadline().equals(row.created().plusMinutes(5))||row.created().isAfter(now()))bad();
  var request=schema.validate("Publish",schema.read(row.request()));if(!row.request().equals(schema.canonical(request))||!row.requestHash().equals(requestHash(row.tenant(),row.actor(),request))||!row.payloadHash().equals(WireValues.sha256(row.payload().getBytes(StandardCharsets.UTF_8)))||!row.payload().equals(schema.canonical(schema.read(row.payload())))||!row.authorityHash().equals(schema.hash(schema.read(row.authority()))))bad();
  var op=one(operations(a,row.actor(),row.key()));if(!op.id().equals(row.operation())||!op.target().equals(row.release())||!op.requestHash().equals(row.requestHash())||!op.schemaVersion().equals(row.schemaVersion())||!op.manifest().equals(row.schemaManifest())||!op.created().equals(row.created())||!op.creator().equals(row.actor())||!op.classification().equals(row.classification())||op.updated().isBefore(row.created())||op.updated().isAfter(now())||("PROCESSING".equals(op.state())&&(op.httpStatus()!=202||op.response()!=null))||("COMPLETED".equals(op.state())&&(op.httpStatus()!=200||op.response()==null))||(op.revision()==1&&!op.updated().equals(row.created()))||!("PROCESSING".equals(op.state())&&Set.of(1,2).contains(op.revision())||"COMPLETED".equals(op.state())&&op.revision()==3))bad();
  var auth=schema.read(row.authority());var parser=com.fasterxml.jackson.databind.json.JsonMapper.builder().addModule(new com.fasterxml.jackson.datatype.jsr310.JavaTimeModule()).propertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE).build();var grant=parser.treeToValue(auth.required("publication_write"),PermissionProtocol.GrantRow.class);
  var scope=new PermissionProtocol.Scope(row.tenant(),row.project(),row.project()==null?"ENTERPRISE":"PROJECT",row.project()==null?row.tenant():row.project());if(new PermissionAuthority(json).findResource(scope,row.actor(),row.identityMode(),"agent.publish","AGENT_PUBLICATION",List.of(grant),row.created()).isEmpty()||!row.identityMode().equals(auth.required("identity_mode").asText()))bad();
  String expected=anchor(row);var audit=one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id <=> ? AND subject_id=? AND created_by=? AND action='agent.publication.prepared' AND result='SUCCESS' AND reason_code IS NULL AND request_id=? AND trace_id=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND classification=? AND created_at=? LIMIT 2",(r,n)->r.getString(1),row.tenant(),row.project(),row.actor(),row.actor(),row.operation(),row.write(),row.schemaManifest(),row.classification(),row.created()));var event=one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type='agent.publication.prepared' AND occurred_at=? LIMIT 2",(r,n)->r.getString(1),row.tenant(),row.write(),row.release(),row.created()));if(!expected.equals(schema.canonical(schema.read(audit)))||!expected.equals(schema.canonical(schema.read(event))))bad();
 }
 private List<Row> rows(EnterpriseAccess.Admission a,String key){return rows(a,a.actorId(),key);}
 private List<Row> rows(EnterpriseAccess.Admission a,String historicalActor,String key){return db.query("SELECT * FROM formal_agent_publication_intent WHERE tenant_id=? AND created_by=? AND idempotency_key=? LIMIT 2 FOR UPDATE",(r,n)->new Row(r.getString("tenant_id"),r.getString("project_id"),r.getString("created_by"),r.getString("idempotency_key"),r.getString("operation_id"),r.getString("write_id"),r.getString("artifact_id"),r.getString("acceptance_id"),r.getString("acceptance_sha256"),r.getString("candidate_version_id"),r.getString("candidate_sha256"),r.getString("expected_revision"),r.getString("request_json"),r.getString("request_sha256"),r.getString("canonical_payload"),r.getString("payload_sha256"),r.getString("object_key"),r.getString("authorizations_json"),r.getString("authorizations_sha256"),r.getString("identity_mode"),r.getString("schema_version"),r.getString("schema_manifest_sha256"),r.getString("classification"),r.getTimestamp("created_at").toLocalDateTime(),r.getTimestamp("deadline").toLocalDateTime(),r.getString("release_id")),a.context().tenant_id(),historicalActor,key);}
 private List<Operation> operations(EnterpriseAccess.Admission a,String key){return operations(a,a.actorId(),key);}
 private List<Operation> operations(EnterpriseAccess.Admission a,String historicalActor,String key){return db.query("SELECT operation_id,request_sha256,state,revision,response_ref,target_id,schema_version,schema_manifest_sha256,created_at,created_by,classification,http_status,updated_at FROM operation_record WHERE tenant_id=? AND subject_id=? AND operation_name=? AND idempotency_key=? LIMIT 2 FOR UPDATE",(r,n)->new Operation(r.getString(1),r.getString(2),r.getString(3),r.getInt(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getTimestamp(9).toLocalDateTime(),r.getString(10),r.getString(11),r.getInt(12),r.getTimestamp(13).toLocalDateTime()),a.context().tenant_id(),historicalActor,OPERATION,key);}
 private String anchor(Row row)throws Exception{return schema.canonical(AgentPublicationWitness.tree(row));}
 private String requestHash(String tenant,String actor,JsonNode request)throws Exception{return schema.hash(Map.of("operation",OPERATION,"tenant_id",tenant,"actor_id",actor,"body",request,"schema_manifest",schema.manifest()));}
 private LocalDateTime now(){return one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));}
 private static String key(String tenant,String release,String write,String artifact){return "publication/"+tenant+"/"+release+"/"+write+"/"+artifact;}
 private static String id(){return UUID.randomUUID().toString();}private static void scope(EnterpriseAccess.Admission a){var t=TenantScope.requireCurrent();if(!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()||!t.tenantId().equals(a.context().tenant_id())||!t.subjectId().equals(a.actorId()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
 private static <T>T one(List<T> values){if(values.size()!=1||values.get(0)==null)bad();return values.get(0);}private static void one(int n){if(n!=1)bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
